Ниже готовый код: четыре файла и пример экрана. Собрать его я не мог, потому что у меня нет Xcode. Перед проверкой посмотрите в «Допущениях» пункты про то, как устроена модель `Quote` и как сейчас создаётся хранилище.

## 1. `QuoteItem.swift`: цитата, с которой работают экраны

```swift
import Foundation

struct QuoteItem: Identifiable, Hashable, Sendable {
    let id: UUID
    let text: String
    let bookID: UUID
    let createdAt: Date
}
```

## 2. `QuoteRepository.swift`: что хранилище умеет делать

```swift
import Foundation

protocol QuoteRepository: Sendable {
    /// Returns quotes of the book, newest first.
    func quotes(forBookID bookID: UUID) async throws -> [QuoteItem]
    func addQuote(text: String, bookID: UUID) async throws -> QuoteItem
    func deleteQuote(id: UUID) async throws
}
```

## 3. `SwiftDataQuoteRepository.swift`: текущая реализация на SwiftData

```swift
import Foundation
import SwiftData

@MainActor
final class SwiftDataQuoteRepository: QuoteRepository {
    private let context: ModelContext

    init(modelContainer: ModelContainer) {
        context = modelContainer.mainContext
    }

    func quotes(forBookID bookID: UUID) async throws -> [QuoteItem] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try context.fetch(descriptor).map(QuoteItem.init)
    }

    func addQuote(text: String, bookID: UUID) async throws -> QuoteItem {
        let quote = Quote(id: UUID(), text: text, bookID: bookID, createdAt: .now)
        context.insert(quote)
        try saveOrRollback()
        return QuoteItem(quote)
    }

    func deleteQuote(id: UUID) async throws {
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == id })
        for quote in try context.fetch(descriptor) {
            context.delete(quote)
        }
        try saveOrRollback()
    }

    // A failed save must not leave unsaved inserts/deletes in the shared main context.
    private func saveOrRollback() throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }
}

private extension QuoteItem {
    init(_ quote: Quote) {
        self.init(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
```

## 4. Подключение в приложении

```swift
import SwiftUI
import SwiftData

@main
struct BooksApp: App {
    private let container: ModelContainer
    private let quoteRepository: any QuoteRepository

    init() {
        do {
            // Keep the same model list and configuration the app already uses.
            container = try ModelContainer(for: Quote.self)
        } catch {
            fatalError("Failed to create ModelContainer: \(error)")
        }
        quoteRepository = SwiftDataQuoteRepository(modelContainer: container)
    }

    var body: some Scene {
        WindowGroup {
            ContentView(quoteRepository: quoteRepository)
        }
        .modelContainer(container)
    }
}
```

## 5. Пример экрана: как пользоваться хранилищем

```swift
import SwiftUI

struct BookQuotesView: View {
    let bookID: UUID
    let repository: any QuoteRepository

    @State private var quotes: [QuoteItem] = []
    @State private var newText = ""
    @State private var errorMessage: String?

    var body: some View {
        List {
            Section {
                TextField("Новая цитата", text: $newText, axis: .vertical)
                Button("Добавить") {
                    Task { await add() }
                }
                .disabled(newText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }

            if let errorMessage {
                Text(errorMessage).foregroundStyle(.red)
            }

            ForEach(quotes) { quote in
                Text(quote.text)
            }
            .onDelete { offsets in
                let ids = offsets.map { quotes[$0].id }
                Task { await delete(ids) }
            }
        }
        .task { await load() }
    }

    private func load() async {
        do {
            quotes = try await repository.quotes(forBookID: bookID)
        } catch {
            errorMessage = "Не удалось загрузить цитаты: \(error.localizedDescription)"
        }
    }

    private func add() async {
        let text = newText.trimmingCharacters(in: .whitespacesAndNewlines)
        do {
            let quote = try await repository.addQuote(text: text, bookID: bookID)
            quotes.insert(quote, at: 0)
            newText = ""
        } catch {
            errorMessage = "Не удалось сохранить цитату: \(error.localizedDescription)"
        }
    }

    private func delete(_ ids: [UUID]) async {
        do {
            for id in ids {
                try await repository.deleteQuote(id: id)
            }
            quotes.removeAll { ids.contains($0.id) }
        } catch {
            errorMessage = "Не удалось удалить цитату: \(error.localizedDescription)"
        }
    }
}
```

## Ключевые решения

- **Экраны не видят SwiftData.** Они знают только `QuoteItem` и `QuoteRepository`, в этих файлах нет ни слова о SwiftData. Чтобы перейти на GRDB, нужно написать один новый файл с той же «вывеской» и поменять одну строку в подключении. Экраны переписывать не придётся.
- **Экраны получают простую копию данных, а не сам объект базы.** `QuoteItem` — это данные только для чтения. Объекты SwiftData привязаны к своему потоку и сами меняются со временем. С копией нельзя случайно испортить базу, и строгая проверка многопоточности Swift 6 к ней не придирается.
- **Все методы асинхронные (`async throws`).** Сейчас SwiftData отвечает мгновенно. Но GRDB, скорее всего, будет работать в фоне, а с асинхронными методами экраны ничего не заметят. Ошибки возвращаются экрану, чтобы показать их пользователю.
- **SwiftData работает на главном потоке (`@MainActor`, `mainContext`), а не через фоновый `@ModelActor`.** Цитаты — короткие тексты, их немного, так что скорость не страдает. Зато такой вариант самый простой и надёжный: у фонового режима SwiftData есть известные странности с обновлениями.
- **Если сохранение не удалось, изменение отменяется (`rollback`).** Иначе несохранённая цитата могла бы «висеть» в памяти и записаться позже, при чужом сохранении.
- **Экран сам обновляет свой список** после добавления или удаления, повторно из базы ничего не загружается. Автоматическое обновление при изменениях из других мест вы не просили, поэтому его нет.

## Допущения

1. У `id` и `bookID` тип `UUID`. Если `bookID` другого типа, например `String`, его нужно заменить в трёх местах: `QuoteItem`, протокол и реализация.
2. Модель `Quote` создаётся так: `Quote(id:text:bookID:createdAt:)`. Если у неё другой инициализатор, поправить нужно одну строку в `addQuote`.
3. Саму модель `Quote` я не трогаю и не переименовываю: у SwiftData переименование может сломать уже сохранённые данные. Поэтому тип для экранов называется `QuoteItem`.
4. Пустые цитаты не даёт добавить экран: кнопка выключена, а пробелы по краям обрезаются. Само хранилище текст не проверяет.
5. В разделе 4 хранилище создаётся явно. Если в приложении уже есть свой `ModelContainer` с другими моделями (например, книгами), репозиторию нужно передать именно его, а не создавать новый.
6. Переход на GRDB — это новая реализация хранилища. Перенос уже сохранённых цитат из SwiftData в GRDB — отдельная задача, она будет нужна в момент перехода.

