## 1. `QuoteStore.swift`: то, с чем работают экраны

```swift
import Foundation
import SwiftUI

/// Storage-independent quote value used by screens.
struct QuoteItem: Identifiable, Hashable, Sendable {
    let id: UUID
    let text: String
    let bookID: UUID
    let createdAt: Date
}

/// Quote storage contract. Screens depend only on this protocol,
/// so the backing database (SwiftData now, GRDB later) can be swapped.
protocol QuoteStore: Sendable {
    /// Quotes of the book, newest first.
    func quotes(forBook bookID: UUID) async throws -> [QuoteItem]
    func addQuote(text: String, toBook bookID: UUID) async throws -> QuoteItem
    /// Deleting a missing quote is a no-op.
    func deleteQuote(id: UUID) async throws
}

extension EnvironmentValues {
    @Entry var quoteStore: any QuoteStore = UnconfiguredQuoteStore()
}

/// Default environment value: fails loudly instead of silently losing data
/// when the real store was not injected at the app root.
private struct UnconfiguredQuoteStore: QuoteStore {
    struct NotConfiguredError: LocalizedError {
        var errorDescription: String? { "Quote storage is not configured" }
    }

    func quotes(forBook bookID: UUID) async throws -> [QuoteItem] { throw NotConfiguredError() }
    func addQuote(text: String, toBook bookID: UUID) async throws -> QuoteItem { throw NotConfiguredError() }
    func deleteQuote(id: UUID) async throws { throw NotConfiguredError() }
}
```

## 2. `SwiftDataQuoteStore.swift`: реализация на SwiftData (при переходе её заменит GRDB-версия)

```swift
import Foundation
import SwiftData

@MainActor
final class SwiftDataQuoteStore: QuoteStore {
    private let context: ModelContext

    init(modelContainer: ModelContainer) {
        context = modelContainer.mainContext
    }

    func quotes(forBook bookID: UUID) throws -> [QuoteItem] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try context.fetch(descriptor).map(QuoteItem.init)
    }

    func addQuote(text: String, toBook bookID: UUID) throws -> QuoteItem {
        let quote = Quote(id: UUID(), text: text, bookID: bookID, createdAt: .now)
        context.insert(quote)
        try context.save()
        return QuoteItem(quote)
    }

    func deleteQuote(id: UUID) throws {
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == id })
        for quote in try context.fetch(descriptor) {
            context.delete(quote)
        }
        try context.save()
    }
}

private extension QuoteItem {
    init(_ quote: Quote) {
        self.init(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
```

