```swift
import SwiftUI

struct BookQuotesView: View {
    let bookID: UUID

    @Environment(\.quoteStore) private var store
    @State private var quotes: [QuoteItem] = []
    @State private var newText = ""
    @State private var errorText: String?

    var body: some View {
        List {
            if let errorText {
                Text(errorText).foregroundStyle(.red)
            }
            Section {
                TextField("Новая цитата", text: $newText, axis: .vertical)
                Button("Добавить") { Task { await add() } }
                    .disabled(trimmedText.isEmpty)
            }
            Section {
                ForEach(quotes) { quote in
                    Text(quote.text)
                }
                .onDelete { offsets in
                    let ids = offsets.map { quotes[$0].id }
                    Task { await delete(ids) }
                }
            }
        }
        .task(id: bookID) { await load() }
    }

    private var trimmedText: String {
        newText.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func load() async {
        do {
            quotes = try await store.quotes(forBook: bookID)
        } catch {
            errorText = error.localizedDescription
        }
    }

    private func add() async {
        do {
            let quote = try await store.addQuote(text: trimmedText, toBook: bookID)
            quotes.insert(quote, at: 0)
            newText = ""
        } catch {
            errorText = error.localizedDescription
        }
    }

    private func delete(_ ids: [UUID]) async {
        do {
            for id in ids {
                try await store.deleteQuote(id: id)
                quotes.removeAll { $0.id == id }
            }
        } catch {
            errorText = error.localizedDescription
        }
    }
}
