    static func validatedText(_ raw: String) throws -> String {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { throw QuoteRepositoryError.emptyText }
        return text
    }
}

enum QuoteRepositoryError: LocalizedError {
    case emptyText

    var errorDescription: String? {
        switch self {
        case .emptyText: "Цитата не может быть пустой."
        }
    }
}
```

### 2. `QuoteRepository.swift`: договорённость между экранами и хранилищем

