### 3. `QuoteBroadcaster.swift`: рассылает свежий список открытым экранам

```swift
import Foundation

/// Помнит, какие экраны следят за какими книгами, и присылает им новый список после изменений.
@MainActor
final class QuoteBroadcaster {
    private struct Subscriber {
        let bookID: UUID
        let continuation: AsyncThrowingStream<[QuoteItem], Error>.Continuation
    }

    private var subscribers: [UUID: Subscriber] = [:]

    func subscribe(
        bookID: UUID,
        fetch: () throws -> [QuoteItem]
    ) -> AsyncThrowingStream<[QuoteItem], Error> {
        // Экрану нужен только последний список, промежуточные не копим.
        let (stream, continuation) = AsyncThrowingStream.makeStream(
            of: [QuoteItem].self,
            bufferingPolicy: .bufferingNewest(1)
        )
        let token = UUID()
        subscribers[token] = Subscriber(bookID: bookID, continuation: continuation)

        // Экран закрылся: перестаём слать ему обновления.
        continuation.onTermination = { _ in
            Task { @MainActor in self.subscribers[token] = nil }
        }

        do {
            continuation.yield(try fetch())
        } catch {
            continuation.finish(throwing: error)
        }
        return stream
    }

    func notify(bookID: UUID, fetch: () throws -> [QuoteItem]) {
        let targets = subscribers.values.filter { $0.bookID == bookID }
        guard !targets.isEmpty else { return }
        do {
            let items = try fetch()
            targets.forEach { $0.continuation.yield(items) }
        } catch {
            targets.forEach { $0.continuation.finish(throwing: error) }
        }
    }
}
```

### 4. `SwiftDataQuoteRepository.swift`: единственное место, где цитаты связаны со SwiftData

```swift
import Foundation
import SwiftData

@MainActor
final class SwiftDataQuoteRepository: QuoteRepository {
    private let context: ModelContext
    private let broadcaster = QuoteBroadcaster()

    init(container: ModelContainer) {
        self.context = container.mainContext
    }

    func quotes(ofBook bookID: UUID) -> AsyncThrowingStream<[QuoteItem], Error> {
        broadcaster.subscribe(bookID: bookID) { try fetch(bookID: bookID) }
    }

    func addQuote(text: String, toBook bookID: UUID) async throws -> QuoteItem {
        let quote = Quote(
            id: UUID(),
            text: try QuoteItem.validatedText(text),
            bookID: bookID,
            createdAt: .now
        )
        context.insert(quote)
        try save()
        broadcaster.notify(bookID: bookID) { try fetch(bookID: bookID) }
        return QuoteItem(quote)
    }

    func deleteQuote(id: UUID) async throws {
        var descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == id })
        descriptor.fetchLimit = 1
        guard let quote = try context.fetch(descriptor).first else { return }

        let bookID = quote.bookID
        context.delete(quote)
        try save()
        broadcaster.notify(bookID: bookID) { try fetch(bookID: bookID) }
    }

    private func fetch(bookID: UUID) throws -> [QuoteItem] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try context.fetch(descriptor).map { QuoteItem($0) }
    }

    /// Если сохранить не удалось, отменяем несохранённые изменения, чтобы данные не разошлись с экраном.
    private func save() throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }
}

private extension QuoteItem {
    init(_ quote: Quote) {
        self.init(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
