import Foundation
import SwiftUI

/// Поток списков цитат: сразу текущий список, затем новый после каждого изменения.
typealias QuoteListStream = AsyncThrowingStream<[QuoteItem], any Error>

/// Всё, что экранам нужно от хранилища цитат.
/// Любая реализация (SwiftData, GRDB, тестовая) обязана уметь ровно это.
@MainActor
protocol QuoteRepository: Sendable {
    /// Цитаты книги, новые сверху. Список обновляется сам после добавления и удаления.
    func quotes(bookID: UUID) -> QuoteListStream

    @discardableResult
    func addQuote(text: String, bookID: UUID) async throws -> QuoteItem

    /// Удаление уже удалённой цитаты не считается ошибкой.
    func deleteQuote(id: UUID) async throws
}

enum QuoteRepositoryError: LocalizedError {
    case notConfigured

    var errorDescription: String? {
        switch self {
        case .notConfigured:
            "Хранилище цитат не подключено к экрану."
        }
    }
}

/// Заглушка «по умолчанию». Если хранилище забыли передать экрану,
/// экран покажет понятную ошибку, а не будет молча терять данные.
@MainActor
final class MissingQuoteRepository: QuoteRepository {
    nonisolated init() {}

    func quotes(bookID: UUID) -> QuoteListStream {
        QuoteListStream { $0.finish(throwing: QuoteRepositoryError.notConfigured) }
    }

    func addQuote(text: String, bookID: UUID) throws -> QuoteItem {
        throw QuoteRepositoryError.notConfigured
    }

    func deleteQuote(id: UUID) throws {
        throw QuoteRepositoryError.notConfigured
    }
}

extension EnvironmentValues {
    /// Хранилище цитат, доступное любому экрану через @Environment(\.quoteRepository).
    @Entry var quoteRepository: any QuoteRepository = MissingQuoteRepository()
}
