```swift
import Foundation
import SwiftData

/// Хранилище цитат на SwiftData. Единственное место в приложении,
/// которое знает, что цитаты лежат в SwiftData.
@MainActor
final class SwiftDataQuoteRepository: QuoteRepository {
    private struct Subscriber {
        let bookID: UUID
        let continuation: QuoteListStream.Continuation
    }

    private let context: ModelContext
    private var subscribers: [UUID: Subscriber] = [:]

    init(container: ModelContainer) {
        context = container.mainContext
    }

    func quotes(bookID: UUID) -> QuoteListStream {
        let (stream, continuation) = QuoteListStream.makeStream(bufferingPolicy: .bufferingNewest(1))
        let token = UUID()
        subscribers[token] = Subscriber(bookID: bookID, continuation: continuation)
        continuation.onTermination = { [weak self] _ in
            Task { @MainActor in self?.subscribers[token] = nil }
        }
        send(bookID: bookID, to: continuation)
        return stream
    }

    @discardableResult
    func addQuote(text: String, bookID: UUID) throws -> QuoteItem {
        let quote = Quote(id: UUID(), text: text, bookID: bookID, createdAt: .now)
        context.insert(quote)
        try save()
        let item = QuoteItem(quote)
        notifySubscribers(bookID: bookID)
        return item
    }

    func deleteQuote(id: UUID) throws {
        let quoteID = id
        var descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == quoteID })
        descriptor.fetchLimit = 1
        guard let quote = try context.fetch(descriptor).first else { return }
        let bookID = quote.bookID
        context.delete(quote)
        try save()
        notifySubscribers(bookID: bookID)
    }

    // MARK: - Private

    private func fetchQuotes(bookID: UUID) throws -> [QuoteItem] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try context.fetch(descriptor).map(QuoteItem.init)
    }

    /// Если сохранить не удалось, отменяем несохранённые изменения,
    /// чтобы на экране не осталась цитата, которой нет на диске.
    private func save() throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }

    private func notifySubscribers(bookID: UUID) {
        for subscriber in subscribers.values where subscriber.bookID == bookID {
            send(bookID: bookID, to: subscriber.continuation)
        }
    }

    private func send(bookID: UUID, to continuation: QuoteListStream.Continuation) {
        do {
            continuation.yield(try fetchQuotes(bookID: bookID))
        } catch {
            continuation.finish(throwing: error)
        }
    }
}

private extension QuoteItem {
    init(_ quote: Quote) {
        self.init(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
    }
}
```

