import SwiftData

@Model
final class Book {
    var id: UUID
    var title: String
    var author: String
    var addedAt: Date

    // Covers live in separate models so fetching the library never loads image bytes.
    @Relationship(deleteRule: .cascade, inverse: \BookCoverThumbnail.book)
    var coverThumbnail: BookCoverThumbnail?

    @Relationship(deleteRule: .cascade, inverse: \BookCoverImage.book)
    var coverImage: BookCoverImage?

