        self.id = id
        self.title = title
        self.author = author
        self.addedAt = addedAt
    }
}

/// Small JPEG (~15 KB) shown in the library list.
@Model
final class BookCoverThumbnail {
    var data: Data = Data()
    var book: Book?

    init(data: Data) {
        self.data = data
    }
}

/// Larger JPEG (~200 KB) shown on the book screen; stored as a file outside the database.
@Model
final class BookCoverImage {
    @Attribute(.externalStorage) var data: Data = Data()
    var book: Book?

    init(data: Data) {
        self.data = data
    }
}

extension Book {
    @MainActor
    func setCover(_ cover: ProcessedCover, in context: ModelContext) {
        if let coverThumbnail {
            coverThumbnail.data = cover.thumbnail
        } else {
            let thumbnail = BookCoverThumbnail(data: cover.thumbnail)
            context.insert(thumbnail)
            coverThumbnail = thumbnail
        }

        if let coverImage {
            coverImage.data = cover.image
        } else {
            let image = BookCoverImage(data: cover.image)
            context.insert(image)
            coverImage = image
        }

        ThumbnailCache.shared.remove(for: self)
        try? context.save()
    }
}
