### `CoverProcessor.swift`

```swift
import UIKit

nonisolated struct ProcessedCover: Sendable {
    let image: Data
    let thumbnail: Data
}

nonisolated enum CoverProcessor {
    static let imageMaxSide: CGFloat = 1200
    static let thumbnailMaxSide: CGFloat = 240

    /// Downscales a 12 MP camera photo off the main thread and encodes both sizes as JPEG.
    static func process(_ photo: UIImage) async -> ProcessedCover? {
        await Task.detached(priority: .userInitiated) { () -> ProcessedCover? in
            let image = Self.resized(photo, maxSide: imageMaxSide)
            // Thumbnail is made from the already reduced image: much cheaper than from 12 MP.
            let thumbnail = Self.resized(image, maxSide: thumbnailMaxSide)
            guard let imageData = image.jpegData(compressionQuality: 0.8),
                  let thumbnailData = thumbnail.jpegData(compressionQuality: 0.7)
            else { return nil }
            return ProcessedCover(image: imageData, thumbnail: thumbnailData)
        }.value
    }

    private static func resized(_ image: UIImage, maxSide: CGFloat) -> UIImage {
        let ratio = min(1, maxSide / max(image.size.width, image.size.height))
        let size = CGSize(
            width: (image.size.width * ratio).rounded(),
            height: (image.size.height * ratio).rounded()
        )
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        // draw(in:) applies the camera orientation, so the result is always upright.
        return UIGraphicsImageRenderer(size: size, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: size))
        }
    }
}
```

### `ThumbnailCache.swift`

```swift
import UIKit

/// Keeps decoded list thumbnails in memory so scrolling back does not flicker.
@MainActor
final class ThumbnailCache {
    static let shared = ThumbnailCache()

    private let cache = NSCache<NSString, UIImage>()

    private init() {
        cache.totalCostLimit = 32 * 1024 * 1024
    }

    func image(for book: Book) -> UIImage? {
        cache.object(forKey: key(for: book))
    }

    func insert(_ image: UIImage, for book: Book) {
        let pixels = image.size.width * image.scale * image.size.height * image.scale
        cache.setObject(image, forKey: key(for: book), cost: Int(pixels) * 4)
    }

    func remove(for book: Book) {
        cache.removeObject(forKey: key(for: book))
    }

    private func key(for book: Book) -> NSString {
        "\(book.id)" as NSString
    }
}
