        self.data = data
    }
}

extension Book {
    @MainActor
    func setCover(_ cover: ProcessedCover, in context: ModelContext) {
        if let coverThumbnail {
            coverThumbnail.data = cover.thumbnail
        } else {
            let thumbnail = BookCoverThumbnail(data: cover.thumbnail)
            context.insert(thumbnail)
            coverThumbnail = thumbnail
