import SwiftUI
import SwiftData

/// Cover in a library list row.
struct CoverThumbnailView: View {
    let book: Book
    @State private var image: UIImage?

    init(book: Book) {
        self.book = book
        _image = State(initialValue: ThumbnailCache.shared.image(for: book))
    }

    var body: some View {
        RoundedRectangle(cornerRadius: 4)
            .fill(.quaternary)
            .overlay {
                if let image {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                } else {
                    Image(systemName: "book.closed")
                        .foregroundStyle(.secondary)
                }
            }
            .frame(width: 48, height: 72)
            .clipShape(RoundedRectangle(cornerRadius: 4))
            .task(id: book.coverThumbnail?.data) { await load() }
    }

    private func load() async {
        guard let data = book.coverThumbnail?.data else {
            image = nil
            return
        }
        if let cached = ThumbnailCache.shared.image(for: book) {
            image = cached
            return
        }
        // byPreparingForDisplay decodes the JPEG off the main thread.
        guard let decoded = await UIImage(data: data)?.byPreparingForDisplay() else { return }
        ThumbnailCache.shared.insert(decoded, for: book)
        image = decoded
    }
}

/// Large cover on the book screen.
