            if let shown = image ?? ThumbnailCache.shared.image(for: book) {
                Image(uiImage: shown)
                    .resizable()
                    .scaledToFit()
                    .clipShape(RoundedRectangle(cornerRadius: 8))
            } else {
                RoundedRectangle(cornerRadius: 8)
                    .fill(.quaternary)
                    .aspectRatio(2 / 3, contentMode: .fit)
                    .overlay {
                        Image(systemName: "book.closed")
                            .font(.largeTitle)
                            .foregroundStyle(.secondary)
                    }
            }
        }
        .frame(maxWidth: 240, maxHeight: 360)
        .task(id: data) {
            guard let data else {
                image = nil
                return
            }
            image = await UIImage(data: data)?.byPreparingForDisplay()
        }
    }
}

/// Cover plus "take photo" button for the book screen.
