## 2. Обработка фото — `CoverImageProcessor.swift`

```swift
import UIKit

enum CoverImageProcessor {
    private static let fullMaxSide: CGFloat = 1200
    private static let thumbnailMaxSide: CGFloat = 240

    /// Heavy work: call off the main thread.
    nonisolated static func process(_ photo: UIImage) -> (full: Data, thumbnail: Data)? {
        autoreleasepool {
            let full = resized(photo, maxSide: fullMaxSide)
            let thumbnail = resized(full, maxSide: thumbnailMaxSide)
            guard let fullData = full.jpegData(compressionQuality: 0.8),
                  let thumbnailData = thumbnail.jpegData(compressionQuality: 0.7)
            else { return nil }
            return (fullData, thumbnailData)
        }
    }

    nonisolated private static func resized(_ image: UIImage, maxSide: CGFloat) -> UIImage {
        let pixelSize = CGSize(width: image.size.width * image.scale,
                               height: image.size.height * image.scale)
        let ratio = min(1, maxSide / max(pixelSize.width, pixelSize.height))
        let target = CGSize(width: (pixelSize.width * ratio).rounded(),
                            height: (pixelSize.height * ratio).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard

        // draw(in:) applies the camera orientation, so the result is always upright.
        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }
}
```

## 3. Отображение — `BookCoverViews.swift`

```swift
import SwiftUI
import UIKit

@MainActor
final class CoverThumbnailCache {
    static let shared = CoverThumbnailCache()
    private let cache = NSCache<NSUUID, UIImage>()

    private init() {
        cache.countLimit = 200
    }

    func image(for id: UUID) -> UIImage? {
        cache.object(forKey: id as NSUUID)
    }

    func insert(_ image: UIImage, for id: UUID) {
        cache.setObject(image, forKey: id as NSUUID)
    }
}

struct CoverPlaceholder: View {
    var body: some View {
        Rectangle()
            .fill(.quaternary)
            .overlay {
                Image(systemName: "book.closed")
                    .foregroundStyle(.secondary)
            }
    }
}

/// Small cover for library rows.
struct BookCoverThumbnail: View {
    let cover: BookCover?
    @State private var image: UIImage?

    init(cover: BookCover?) {
        self.cover = cover
        _image = State(initialValue: cover.flatMap { CoverThumbnailCache.shared.image(for: $0.id) })
    }

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFill()
            } else {
                CoverPlaceholder()
            }
        }
        .frame(width: 44, height: 66)
        .clipShape(RoundedRectangle(cornerRadius: 4))
        .task(id: cover?.id) { await load() }
    }

    private func load() async {
        guard let cover else {
            image = nil
            return
        }
        let id = cover.id
        if let cached = CoverThumbnailCache.shared.image(for: id) {
            image = cached
            return
        }
        image = nil
        guard let decoded = await UIImage(data: cover.thumbnailData)?.byPreparingForDisplay() else { return }
        CoverThumbnailCache.shared.insert(decoded, for: id)
        image = decoded
    }
}

/// Large cover for the book screen.
struct BookCoverImage: View {
    let cover: BookCover?
    @State private var image: UIImage?

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else {
                CoverPlaceholder()
                    .aspectRatio(2 / 3, contentMode: .fit)
            }
        }
        .frame(maxHeight: 320)
        .clipShape(RoundedRectangle(cornerRadius: 8))
        .task(id: cover?.id) {
            guard let cover else {
                image = nil
                return
            }
            // Show the cached thumbnail instantly while the full image decodes.
            image = CoverThumbnailCache.shared.image(for: cover.id)
            if let full = await UIImage(data: cover.imageData)?.byPreparingForDisplay() {
                image = full
            }
        }
    }
}
```

