## 1. `Book.swift`: модели

Если файл `Book` у вас уже есть, не заменяйте его целиком. Добавьте в него только свойство `cover` с атрибутом `@Relationship` (помечено комментарием), а остальное возьмите из этого файла.

```swift
import Foundation
import SwiftData

@Model
final class Book {
    var id: UUID = UUID()
    var title: String = ""
    var author: String = ""
    var addedAt: Date = Date.now

    // ДОБАВИТЬ: обложка лежит отдельной записью, чтобы список книг не грузил картинки
    @Relationship(deleteRule: .cascade, inverse: \BookCover.book)
    var cover: BookCover?

    init(id: UUID = UUID(), title: String, author: String, addedAt: Date = .now) {
        self.id = id
        self.title = title
        self.author = author
        self.addedAt = addedAt
    }
}

/// Миниатюра для списка (~10 КБ) + ссылка на большое изображение.
@Model
final class BookCover {
    /// Новый id при каждой замене обложки, по нему работает кэш миниатюр.
    var id: UUID = UUID()
    var thumbnailData: Data = Data()
    var book: Book?

    @Relationship(deleteRule: .cascade, inverse: \BookCoverImage.cover)
    var image: BookCoverImage?

    init(thumbnailData: Data) {
        self.thumbnailData = thumbnailData
    }
}

/// Большое изображение для экрана книги. Хранится отдельным файлом, читается только по требованию.
@Model
final class BookCoverImage {
    @Attribute(.externalStorage) var data: Data = Data()
    var cover: BookCover?

    init(data: Data) {
        self.data = data
    }
}

extension Book {
    func setCover(_ jpegs: CoverImageData) {
        guard let context = modelContext else { return }

        let image = BookCoverImage(data: jpegs.full)
        let newCover = BookCover(thumbnailData: jpegs.thumbnail)
        context.insert(image)
        context.insert(newCover)
        newCover.image = image

        let oldCover = cover
        cover = newCover
        if let oldCover { context.delete(oldCover) }
        try? context.save()
    }

    func removeCover() {
        guard let oldCover = cover else { return }
        cover = nil
        modelContext?.delete(oldCover)
        try? modelContext?.save()
    }
}
```

## 2. `CoverImageProcessor.swift`: уменьшение фото в фоне

```swift
import UIKit

typealias CoverImageData = (full: Data, thumbnail: Data)

enum CoverImageProcessor {
    nonisolated static func makeCover(from image: UIImage) async -> CoverImageData? {
        await Task.detached(priority: .userInitiated) {
            CoverImageProcessor.encode(image)
        }.value
    }

    nonisolated static func makeCover(from data: Data) async -> CoverImageData? {
        await Task.detached(priority: .userInitiated) {
            guard let image = UIImage(data: data) else { return nil }
            return CoverImageProcessor.encode(image)
        }.value
    }

    nonisolated private static func encode(_ image: UIImage) -> CoverImageData? {
        autoreleasepool { () -> CoverImageData? in
            let large = resized(image, maxPixelSize: 1200)
            let small = resized(large, maxPixelSize: 240)
            guard let full = large.jpegData(compressionQuality: 0.75),
                  let thumbnail = small.jpegData(compressionQuality: 0.7) else { return nil }
            return (full: full, thumbnail: thumbnail)
        }
    }

    /// Уменьшает до maxPixelSize по длинной стороне и «запекает» поворот камеры.
    nonisolated private static func resized(_ image: UIImage, maxPixelSize: CGFloat) -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let factor = min(1, maxPixelSize / max(pixelWidth, pixelHeight))
        let target = CGSize(width: (pixelWidth * factor).rounded(),
                            height: (pixelHeight * factor).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard

        return UIGraphicsImageRenderer(size: target, format: format).image { context in
            context.cgContext.interpolationQuality = .high
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }
}
