import SwiftUI
import SwiftData

private struct CoverCleanupModifier: ViewModifier {
    @Environment(\.modelContext) private var modelContext

    func body(content: Content) -> some View {
        content.task {
            // Если книги прочитать не удалось — ничего не удаляем.
            guard let books = try? modelContext.fetch(FetchDescriptor<Book>()) else { return }
            let ids = Set(books.map(\.id))
            await CoverStore.shared.removeOrphans(keeping: ids)
        }
    }
}

extension View {
    /// Удаляет файлы обложек книг, которых больше нет. Вызвать один раз на корневом экране.
