import SwiftUI
import UniformTypeIdentifiers

/// Reading history as a CSV file that opens correctly in Excel and Numbers.
nonisolated struct ReadingHistoryCSV: Transferable {
    nonisolated private struct Row {
        let startedAt: Date
        let duration: TimeInterval
        let timeZoneIdentifier: String
        let title: String
        let author: String
    }

    private let rows: [Row]

    /// Copies plain values only, so the file is built off the main thread
    /// and only when the user actually shares it.
    @MainActor
    init(sessions: [ReadingSession]) {
        rows = sessions.map {
            Row(
                startedAt: $0.startedAt,
                duration: $0.duration,
                timeZoneIdentifier: $0.timeZoneIdentifier,
                title: $0.bookTitle,
                author: $0.bookAuthor
            )
        }
    }

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { csv in
            let url = FileManager.default.temporaryDirectory
                .appending(path: "История чтения.csv")
            // UTF-8 BOM: without it Excel shows Cyrillic as garbage.
            let data = Data([0xEF, 0xBB, 0xBF]) + Data(csv.makeCSV().utf8)
            try data.write(to: url, options: .atomic)
            return SentTransferredFile(url)
        }
    }

    private func makeCSV() -> String {
        // Excel splits columns by the system list separator: ";" in locales with
        // a decimal comma (Russian, German, French...), "," otherwise.
        // Numbers detects either.
        let separator = Locale.current.decimalSeparator == "," ? ";" : ","
        var formatters: [String: DateFormatter] = [:]

        let header = ["Дата и время начала", "Длительность, мин", "Название", "Автор"]
        var lines = [header.map(Self.textField).joined(separator: separator)]

        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            let formatter = formatters[row.timeZoneIdentifier]
                ?? Self.makeDateFormatter(timeZoneIdentifier: row.timeZoneIdentifier)
            formatters[row.timeZoneIdentifier] = formatter

            // Int(_:) crashes on NaN or infinity; a corrupted record must not break the export.
            let minutes = row.duration.isFinite ? max(0, Int((row.duration / 60).rounded())) : 0

            let fields = [
                formatter.string(from: row.startedAt),
                String(minutes),
                Self.textField(row.title),
                Self.textField(row.author),
            ]
            lines.append(fields.joined(separator: separator))
        }

        return lines.joined(separator: "\r\n") + "\r\n"
    }

    /// Local time of the place where the session happened, in a format
    /// both Excel and Numbers recognize as date and time.
    private static func makeDateFormatter(timeZoneIdentifier: String) -> DateFormatter {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        formatter.dateFormat = "yyyy-MM-dd HH:mm"
        return formatter
    }

