    /// so commas, semicolons, quotes and line breaks in titles are safe.
    private static func quoted(_ text: String) -> String {
        "\"" + text.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    /// Prevents spreadsheets from treating text like "=..." as a formula.
    private static func neutralizingFormula(_ text: String) -> String {
        guard let first = text.unicodeScalars.first,
              "=+-@\t\r".unicodeScalars.contains(first) else { return text }
        return "'" + text
    }
}

