import SwiftUI
import UIKit

typealias BookID = String

actor CoverCache {
    static let shared = CoverCache()

    // One entry per book: in-flight task while loading, finished task afterwards.
    private var covers: [BookID: Task<UIImage, any Error>] = [:]

    func cover(for id: BookID) async throws -> UIImage {
        if let existing = covers[id] {
            return try await existing.value
        }

        // Detached so the slow disk read never runs on this actor, regardless of project isolation settings.
        let task = Task.detached { try await loadCoverFromDisk(id: id) }
        covers[id] = task

        do {
            return try await task.value
        } catch {
            // Allow a retry on the next request instead of caching the failure.
            covers[id] = nil
            throw error
        }
    }
}

struct BookCoverView: View {
    let bookID: BookID

    private enum CoverState {
        case loading
        case loaded(UIImage)
        case failed
    }

    @State private var state: CoverState = .loading

    var body: some View {
        Group {
            switch state {
            case .loading:
                ProgressView()
            case .loaded(let image):
                Image(uiImage: image).resizable().scaledToFit()
            case .failed:
                Image(systemName: "book.closed").resizable().scaledToFit().foregroundStyle(.secondary)
            }
        }
        .task(id: bookID) {
            state = .loading
            let image = try? await CoverCache.shared.cover(for: bookID)
            // The view may have switched to another book while this cover was loading.
            guard !Task.isCancelled else { return }
            state = image.map(CoverState.loaded) ?? .failed
        }
    }
}
