## Код

```swift
import SwiftUI
import UIKit

/// Type of the book identifier. Change it if your ids are not strings (e.g. UUID or Int).
typealias BookID = String

/// Shared cover cache. Guarantees that each cover is read from disk at most once at a time,
/// no matter how many screens request it concurrently.
actor CoverCache {
    static let shared = CoverCache()

    /// Loaded covers. NSCache frees memory automatically when the system is low on it.
    private let images = NSCache<NSString, UIImage>()

    /// Covers that are being read from disk right now.
    private var inFlight: [BookID: Task<UIImage, Error>] = [:]

    init(maxImages: Int = 200) {
        images.countLimit = maxImages
    }

    func cover(for id: BookID) async throws -> UIImage {
        let key = "\(id)" as NSString

        // 1. Already in memory.
        if let image = images.object(forKey: key) {
            return image
        }

        // 2. Someone is already loading it: wait for the same result.
        if let task = inFlight[id] {
            return try await task.value
        }

        // 3. Nobody is loading it yet: start the only disk read for this id.
        // Detached so the slow disk work does not run on the cache actor.
        let task = Task.detached(priority: .userInitiated) {
            try await loadCoverFromDisk(id: id)
        }
        inFlight[id] = task
        defer { inFlight[id] = nil }

        let image = try await task.value
        images.setObject(image, forKey: key)
        return image
    }
}

/// Example of using the cache from a screen.
struct BookCoverView: View {
    let bookID: BookID
    @State private var image: UIImage?

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else {
                ProgressView()
            }
        }
        .task(id: bookID) {
            image = nil
            image = try? await CoverCache.shared.cover(for: bookID)
        }
    }
}
```

## Ключевые решения

- **Кеш сделан как `actor`.** Swift сам не даёт двум потокам одновременно менять данные кеша, поэтому код проходит строгую проверку Swift 6 без обходных приёмов.
- **Загрузка с диска происходит один раз.** Первый экран, которому нужна обложка, запускает чтение с диска и записывает его в список «загружается сейчас». Если в это время обложку попросит второй экран, он не начнёт новое чтение, а подождёт то же самое и получит ту же картинку.
- **Чтение с диска идёт отдельно от кеша.** Пока одна обложка грузится медленно, другие экраны получают уже загруженные обложки сразу.
- **Ошибки не запоминаются.** Если чтение не удалось, ошибку получат все экраны, которые ждали эту обложку. При следующем запросе загрузка начнётся заново.
- **Память ограничена.** Кеш хранит до 200 обложек и сам освобождает место, когда системе не хватает памяти. Убранная из памяти обложка при следующем запросе снова загрузится с диска.
- **Уход с экрана не отменяет общую загрузку.** Если один экран закрылся, загрузка продолжается для остальных, кто её ждёт.

## Допущения

1. Id книги — это строка. Если в проекте id другого типа (UUID, число), достаточно поменять одну строку: `typealias BookID = String`.
2. `loadCoverFromDisk(id:)` — обычная функция, доступная из любого места проекта, с таким же названием и параметром, как в вашем описании.
3. Лимит в 200 обложек выбран наугад. Его можно поменять: `CoverCache(maxImages: ...)`.
