///
/// - Готовые обложки хранятся в памяти.
/// - Если обложку уже грузят, повторный запрос ждёт ту же загрузку.
///   Второго чтения с диска не будет.
/// - Если загрузка не удалась, ошибка не запоминается, и следующий запрос попробует снова.
actor CoverCache {
    static let shared = CoverCache()

    /// Загруженные обложки. NSCache сам освобождает память,
    /// когда системе её не хватает.
    private let images = NSCache<NSString, UIImage>()

    /// Обложки, которые сейчас читаются с диска.
    private var inFlight: [BookID: Task<UIImage, Error>] = [:]

    private let loader: @Sendable (BookID) async throws -> UIImage

    init(loader: @escaping @Sendable (BookID) async throws -> UIImage = { id in
        try await loadCoverFromDisk(id: id)
    }) {
        self.loader = loader
    }

    func cover(for id: BookID) async throws -> UIImage {
        let key = "\(id)" as NSString

        // 1. Обложка уже в памяти: отдаём сразу.
        if let image = images.object(forKey: key) {
            return image
        }

        // 2. Обложку уже кто-то грузит: ждём ту же загрузку.
        if let existing = inFlight[id] {
            let image = try await existing.value
            try Task.checkCancellation()
            return image
        }

        // 3. Никто не грузит: запускаем загрузку и регистрируем её
        //    до первого ожидания, чтобы параллельные запросы её увидели.
        let loader = self.loader
        let task = Task.detached(priority: .userInitiated) {
            try await loader(id)
        }
        inFlight[id] = task
        defer { inFlight[id] = nil }

        let image = try await task.value
        images.setObject(image, forKey: key)
        try Task.checkCancellation()
        return image
    }
}

