    let bookID: BookID

    @State private var image: UIImage?
    @State private var failed = false

    var body: some View {
        Group {
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else if failed {
                Image(systemName: "book.closed")
                    .resizable()
                    .scaledToFit()
                    .foregroundStyle(.secondary)
            } else {
                ProgressView()
            }
        }
        .task(id: bookID) {
            image = nil
            failed = false
            do {
                image = try await CoverCache.shared.cover(for: bookID)
            } catch is CancellationError {
                // Экран закрыли или сменилась книга, ничего не показываем.
