import SwiftUI
import UIKit

/// Тип идентификатора книги. Если в проекте id — это Int или UUID,
/// поменяйте только эту строку.
typealias BookID = String

/// Общий кеш обложек.
/// `actor` гарантирует, что к внутренним данным в каждый момент обращается
/// только одна операция, поэтому одновременные запросы с разных экранов безопасны.
actor CoverCache {

    static let shared = CoverCache()

    /// Готовые обложки в памяти. NSCache сам освобождает память,
    /// если системе её не хватает.
    private let memory = NSCache<NSString, UIImage>()

    /// Загрузки, которые уже идут. Второй экран не запускает новую загрузку,
    /// а ждёт результат уже запущенной.
    private var inFlight: [BookID: Task<UIImage, Error>] = [:]

    private let loader: @Sendable (BookID) async throws -> UIImage

    init(
        memoryLimitInBytes: Int = 100 * 1024 * 1024, // ~100 МБ
        loader: @escaping @Sendable (BookID) async throws -> UIImage = { id in
            try await loadCoverFromDisk(id: id)
        }
    ) {
        self.loader = loader
        memory.totalCostLimit = memoryLimitInBytes
    }

    /// Возвращает обложку: из памяти, из уже идущей загрузки или с диска.
    func cover(for id: BookID) async throws -> UIImage {
        let key = id as NSString

        // 1. Уже в памяти: отдаём сразу.
        if let cached = memory.object(forKey: key) {
            return cached
        }

        // 2. Кто-то уже грузит эту обложку: ждём тот же результат.
        if let running = inFlight[id] {
            return try await running.value
        }

        // 3. Никто не грузит: запускаем загрузку и СРАЗУ (до первого await)
        //    записываем её в inFlight, чтобы следующий запрос её увидел.
        let loader = self.loader
        let task = Task.detached(priority: .userInitiated) {
            try await loader(id)
        }
        inFlight[id] = task

        do {
            let image = try await task.value
            memory.setObject(image, forKey: key, cost: Self.cost(of: image))
            inFlight[id] = nil
            return image
        } catch {
            // При ошибке ничего не запоминаем: следующий запрос попробует снова.
            inFlight[id] = nil
            throw error
        }
    }

    /// Примерный объём памяти, который занимает картинка (в байтах).
    private static func cost(of image: UIImage) -> Int {
        let pixels = image.size.width * image.scale * image.size.height * image.scale
        return max(1, Int(pixels) * 4)
    }
}

